const appointmentSlotsCheck = await browserjs(tabId, async () => {
  const urls = [
    { city: "New York, NY", url: "https://www.healthgrades.com/usearch?what=Neurosurgeon&entityCode=PS548&searchType=PracticingSpecialty&where=New%20York%2C%20NY&distances=50&availability=tomorrow%2Conline&pageNum=1&sort.provider=bestmatch" },
    { city: "Houston, TX", url: "https://www.healthgrades.com/usearch?what=Neurosurgeon&entityCode=PS548&searchType=PracticingSpecialty&where=Houston%2C%20TX&distances=50&availability=tomorrow%2Conline&pageNum=1&sort.provider=bestmatch" },
    { city: "Miami, FL", url: "https://www.healthgrades.com/usearch?what=Neurosurgeon&entityCode=PS548&searchType=PracticingSpecialty&where=Miami%2C%20FL&distances=50&availability=tomorrow%2Conline&pageNum=1&sort.provider=bestmatch" }
  ];

  const results = [];

  for (const item of urls) {
    const resp = await fetch(item.url);
    const html = await resp.text();
    const doc = new DOMParser().parseFromString(html, 'text/html');

    // Find all doctor card sections
    // In Healthgrades, each result often has a card container or appointment schedule container
    // Let's search for "Fri" or "Sep 18" or "appt" or "Tomorrow" or buttons
    const cards = [];

    // Find all links to physicians
    const links = Array.from(doc.querySelectorAll('a[href*="/physician/"]')).filter(a => a.textContent.trim().startsWith('Dr.'));

    for (const a of links) {
      const docName = a.textContent.trim();
      // find card parent
      let p = a.parentElement;
      while (p && !p.textContent.includes('Compare') && p !== doc.body) {
        p = p.parentElement;
      }
      const cardText = p ? p.textContent : '';

      // Look for Sep 18 or tomorrow or appts
      const hasFri18 = /Fri[^\n]*?Sep[^\n]*?18/i.test(cardText) || /Sep[^\n]*?18/i.test(cardText);
      const apptMatches = cardText.match(/(?:Fri|Sep 18)[^\n]*?(?:\d+\s+appts?|No\s+appts?)/gi);

      cards.push({
        name: docName,
        href: a.getAttribute('href'),
        hasFri18,
        apptMatches,
        cardSnippet: cardText.slice(0, 300).replace(/\s+/g, ' ')
      });
    }

    results.push({
      city: item.city,
      totalCards: cards.length,
      cardsWithAppts: cards.filter(c => c.apptMatches || c.hasFri18)
    });
  }

  return results;
});

