  // Let's search for keywords in the flight data
  const matches = [];
  const re = /(?:Rustamzadeh|Fernandez-Miranda|appointment|availability|age|birthDate|yearsInPractice|medicalSchoolYear)/gi;
  let m;
  let count = 0;
  while ((m = re.exec(allText)) !== null && count < 20) {
    count++;
    const start = Math.max(0, m.index - 50);
    const end = Math.min(allText.length, m.index + 100);
    matches.push(allText.slice(start, end));
  }
  return {
    totalLength: allText.length,
    matches
  };
});

