const tabId = 118779795;

const parsedData = await browserjs(tabId, async () => {
  const cities = [
    "New York, NY",
    "Houston, TX",
    "Dallas, TX",
    "Chicago, IL",
    "Miami, FL",
    "Atlanta, GA",
    "Phoenix, AZ"
  ];

  const citySummaries = [];

  for (const city of cities) {
    const url = `https://www.healthgrades.com/usearch?what=Neurosurgeon&entityCode=PS548&searchType=PracticingSpecialty&where=${encodeURIComponent(city)}&distances=50&availability=tomorrow%2Conline&pageNum=1&sort.provider=bestmatch`;
    const resp = await fetch(url);
    const html = await resp.text();
    const doc = new DOMParser().parseFromString(html, 'text/html');

    // Find heading
    const heading = doc.querySelector('h1, h2')?.textContent?.trim();

    // Find all doctor links
    const docLinks = Array.from(doc.querySelectorAll('a[href*="/physician/"], a[href*="/providers/"]'))
      .map(a => ({ name: a.textContent.trim(), href: a.getAttribute('href') }))
      .filter(d => d.name.startsWith('Dr.') && !d.name.includes('to\nCompare'));

    // Unique doctors
    const uniqueDocs = [];
    const seen = new Set();
    for (const d of docLinks) {
      if (!seen.has(d.href)) {
        seen.add(d.href);
        uniqueDocs.push(d);
      }
    }

    // Let's also check if there's appointment text
    const apptTexts = Array.from(doc.querySelectorAll('[data-qa-target*="appointment"], [class*="appointment"], [class*="schedule"], .c-single-result'))
      .map(el => el.textContent.trim().slice(0, 100));

    citySummaries.push({
      city,
      heading,
      docsCount: uniqueDocs.length,
      docs: uniqueDocs
    });
  }

  return citySummaries;
});

console.log(JSON.stringify(parsedData, null, 2));

