const tabId = 118779795;

const candidateCheck = await browserjs(tabId, async () => {
  // Let's test candidates from New York, Houston, and Miami
  const candidateUrls = [
    // New York
    "/physician/dr-branko-skovrlj-2jjhl",
    "/physician/dr-cameron-brennan-38dcc",
    "/physician/dr-charles-rosenstein-xqgdp",
    "/physician/dr-raj-shrivastava-xsbl7",
    "/physician/dr-viviane-tabar-y6gd8",
    "/physician/dr-chanland-roonprapunt-3544c",
    "/physician/dr-james-liu-2jvq8",
    "/physician/dr-saadi-ghatan-y5vhf",
    "/physician/dr-robert-gross-xk3x3",
    // Miami
    "/physician/dr-michael-mcdermott-3khwj",
    "/physician/dr-warren-selman-39bjl",
    "/physician/dr-matthew-moore-x9l3w",
    "/physician/dr-evan-packer-y5p6h",
    // Houston
    "/physician/dr-gavin-britz-2h3kb",
    "/physician/dr-robert-rostomily-2q9v9"
  ];

  const results = [];

  for (const path of candidateUrls) {
    try {
      const resp = await fetch(`https://www.healthgrades.com${path}`);
      const html = await resp.text();
      const doc = new DOMParser().parseFromString(html, 'text/html');

      // Find JSON-LD
      let jsonLd = null;
      for (const s of doc.querySelectorAll('script[type="application/ld+json"]')) {
        try {
          const parsed = JSON.parse(s.textContent);
          if (parsed['@graph']) {
            jsonLd = parsed['@graph'].find(g => g['@type'] === 'IndividualPhysician');
          }
        } catch(e) {}
      }

      // Check description
      const desc = jsonLd?.description || '';

      // Look for age or graduation year or experience
      const bodyText = doc.body.textContent;
      const ageMatch = bodyText.match(/\b(\d{2})\s+years\s+old\b/i);
      const gradMatch = desc.match(/graduated.*?(19\d\d|20\d\d)/i) || bodyText.match(/(?:Medical School|Graduated|Graduation)[^\n]*?(19\d\d|20\d\d)/i);
      const expMatch = desc.match(/over\s+(\d+)\s+years\s+of\s+experience/i) || bodyText.match(/(\d+)\+?\s+years\s+of\s+experience/i);

      results.push({
        name: jsonLd?.name || doc.querySelector('h1')?.textContent?.trim(),
        path,
        specialty: jsonLd?.availableService?.name || jsonLd?.medicalSpecialty?.name,
        description: desc,
        age: ageMatch ? ageMatch[1] : null,
        gradYear: gradMatch ? gradMatch[1] : null,
        experienceYears: expMatch ? expMatch[1] : null
      });
    } catch(err) {
      results.push({ path, error: err.message });
    }
  }

  return results;
});

console.log(JSON.stringify(candidateCheck, null, 2));

