const tabId = 118779795;

const cities = [
  "Houston, TX",
  "Dallas, TX",
  "Atlanta, GA",
  "Phoenix, AZ",
  "Philadelphia, PA",
  "Denver, CO",
  "Boston, MA",
  "Seattle, WA"
];

const found = [];

for (const city of cities) {
  const url = `https://www.healthgrades.com/usearch?what=Neurosurgeon&entityCode=PS548&searchType=PracticingSpecialty&where=${encodeURIComponent(city)}&distances=50&availability=tomorrow%2Conline&pageNum=1&sort.provider=bestmatch`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });
  // wait 2s for calendar widget hydration
  await new Promise(r => setTimeout(r, 2500));

  const result = await browserjs(tabId, () => {
    const calendars = Array.from(document.querySelectorAll('.card-calendar'));
    const matches = [];
    for (const cal of calendars) {
      const btn18 = cal.querySelector('[data-qa-target="card-calendar-day-2026-09-18"]');
      if (btn18 && !btn18.disabled) {
        let p = cal;
        while (p && !p.innerText.includes('Dr.') && p !== document.body) {
          p = p.parentElement;
        }
        const nameLink = p ? p.querySelector('a[href*="/physician/"]') : null;
        matches.push({
          name: nameLink ? nameLink.innerText.trim() : 'Unknown',
          href: nameLink ? nameLink.href : null,
          btnText: btn18.innerText.replace(/\s+/g, ' '),
          calText: cal.innerText.slice(0, 150).replace(/\s+/g, ' ')
        });
      }
    }
    return {
      calendarsCount: calendars.length,
      matches
    };
  });

  console.log(`${city}: found ${result.calendarsCount} calendars, ${result.matches.length} matches`);
  if (result.matches.length > 0) {
    found.push({ city, matches: result.matches });
  }
}

console.log("Found matches:", JSON.stringify(found, null, 2));

