const tabId = 118779795;

const slots = await browserjs(tabId, () => {
  // Let's see the calendar elements on the profile page
  const cal = document.querySelector('.calendar-container-new');
  if (!cal) return null;

  // Let's look for day 18 button
  const days = Array.from(cal.querySelectorAll('button, td, [class*="day"]')).map(d => ({
    text: d.innerText.trim(),
    className: d.className,
    disabled: d.hasAttribute('disabled') || d.classList.contains('disabled'),
    ariaLabel: d.getAttribute('aria-label')
  }));

  // Find slot buttons
  const timeSlots = Array.from(cal.querySelectorAll('[class*="slot"], [class*="time"], button')).filter(b => /\b\d{1,2}:\d{2}\s*(?:am|pm)?/i.test(b.innerText)).map(b => b.innerText.trim());

  return {
    day18: days.filter(d => d.text === '18' || d.ariaLabel?.includes('18')),
    timeSlots: timeSlots.slice(0, 15)
  };
});

console.log(JSON.stringify(slots, null, 2));

